    wgHint: "برای شبکه‌های موبایلی که فقط فهرست سفید را اجازه می‌دهند. برنامه (VK Turn Proxy در iOS، Free Turn Proxy در Android، WINGS V) ترافیک WireGuard را از طریق سرورهای TURN تماس‌های VK و با پوشش تماس به این پورت UDP می‌فرستد و پنل آن را به WireGuard داخلی Xray می‌سپارد. پورت باید برای UDP باز باشد. در لینک‌های اشتراک نیست — کاربران لینک‌های برنامه را از صفحهٔ اشتراک می‌گیرند.",
    wgDirectHint: "WireGuard ساده روی پورت UDP مخصوص خود: کلاینت مستقیم به سرور وصل می‌شود، پس هر برنامه WireGuard کار می‌کند. پورت باید برای UDP باز باشد. کاربران پیکربندی را به‌صورت فایل یا QR در صفحه اشتراک می‌گیرند. کلیدها را پنل می‌سازد؛ در پیوندهای اشتراک (Clash، sing-box) نمی‌آید. DPI این پروتکل را به‌راحتی تشخیص می‌دهد — برای شبکه‌های سانسورشده از AmneziaWG استفاده کنید.",
